/// <summary>
/// Extension for formletterparmdata to add the custom query
/// </summary>
[ExtensionOf(classStr(formletterParmData))]
final class METFormletterParmData_Extension
{
}

Method.Source:
    /// <summary>
    ///    Executes the prompt of the <c>ChooseLines</c> query on the client-side if the class is currently
    ///    running on the server.
    /// </summary>
    /// <returns>
    ///    true if the prompt is executed; otherwise, false.
    /// </returns>
    /// <remarks>
    ///    The <c>SysQueryRun</c> class does not support the <c>promptOnClient</c> framework to execute the
    ///    prompt on the client, which gives you multiple client calls when prompting from the server.
    /// </remarks>
    protected boolean  promptChooseLines()
    {
        boolean promptChooseLines;

        promptChooseLines = next promptChooseLines();

        if (this as SalesFormletterParmDataConfirm)
        {
            if (this.parmShowQueryForm() && this.parmMCRPickWaveReference() == '')
            {
                QueryBuildDataSource salesTableQbds = chooseLines.query().dataSourceName(tableStr(SalesTable));
                
                int childCount = salesTableQbds.childDataSourceCount();
                boolean foundCustConfirmJour;

                for (int i = 1; i <= childCount; i++)
                {
                    QueryBuildDataSource childDS = salesTableQbds.childDataSourceNo(i);
                    
                    if (childDS.table() == tableNum(CustConfirmJour))
                    {
                        foundCustConfirmJour = true;
                        break;
                    }
                }
                
                if (!foundCustConfirmJour)
                {
                    METLegalEntityType metLegalEntityType = CompanyInfo::find().METLegalEntityType;

                    switch(metLegalEntityType)
                    {
                        case METLegalEntityType::Liquor:
                        
                            QueryBuildDataSource metLiquorSalesOrderViewdDS = salesTableQbds.addDataSource(tableNum(METLiquorSalesOrderView));
                            metLiquorSalesOrderViewdDS.joinMode(JoinMode::ExistsJoin);
                            metLiquorSalesOrderViewdDS.addLink(fieldNum(Salestable, SalesId), fieldNum(METLiquorSalesOrderView, SalesId));
                            break;
                    }
                } 
            }
        }

        return promptChooseLines;
    }
